O=[{0,2},set(),{0,6}]
def mat(rows): return [[x in row for x in range(11)] for row in rows]
def rot(m,k):
 for _ in range(k): m=[list(row) for row in zip(*m[::-1])]
 return m
def flipud(m): return m[::-1]
def fliplr(m): return [row[::-1] for row in m]
