transforms=[]
for u in [False,True]:
 for l in [False,True]:
  for k in range(4):
   X=rot(B,k)
   if len(X)!=3 or len(X[0])!=11: continue
   if u:X=flipud(X)
   if l:X=fliplr(X)
   transforms.append((f'R rot{k*90} flipud{u} fliplr{l}',X))
